/// <summary>
/// Extension of formDataSource ProdTable in form ProdTableOverview
/// </summary>
[ExtensionOf(formDataSourceStr(ProdTableOverview, ProdTable))]
final class AVAProdTableOverview_ProdTableFds_Extension
{
}

Method.Source:
/// <summary>
/// extension of init method
/// </summary>
public void init()
{
    Args locArgs = this.formRun().args();

    next init();

    if(locArgs
        && locArgs.dataset() == tableNum(ProjTable)
        && locArgs.callerFormControl().name() == 'AVAPmfProcessBatchOverview'
        && (locArgs.callerName() == formStr(ProjTable)
            || locArgs.callerName() == formStr(ProjProjectsListPage)))
    {
        ProjTable locProjTable = locArgs.record();
        this.query().dataSourceNo(1).clearDynalinks();
        this.query().dataSourceNo(1).addRange(fieldNum(ProdTable, AVABatchProjId)).value(queryValue(locProjTable.ProjId));
    }
}
